"""Self-checking testbench for the ``mlkem_bfly`` lane.

Expected values are computed in the testbench with plain ``%`` and multiplication by
the modular inverse of 2, i.e. without sharing any reduction code with the DUT or with
``arith``.  ``STRIDE`` > 1 samples the exhaustive sweeps for quick runs.
"""
from .arith import LAT, Q


def emit_bfly_tb(reduction):
    mont = "1" if reduction == "montgomery" else "0"
    return f"""\
// GENERATED by cmtz.accel.mlkem_ntt.tb_bfly -- do not edit.  reduction = {reduction}
`timescale 1ns/1ps
`ifndef STRIDE
`define STRIDE 1
`endif
module mlkem_bfly_tb;
    localparam Q = {Q}, LAT = {LAT}, MONT = {mont};
    reg clk = 0, rst = 1;
    always #5 clk = ~clk;
    reg v_in = 0, mode = 0;
    reg [11:0] a = 0, b = 0, z = 0;
    wire v_out; wire [11:0] o0, o1;
    mlkem_bfly dut (.clk(clk), .rst(rst), .v_in(v_in), .mode(mode), .a(a), .b(b), .z(z),
                    .v_out(v_out), .o0(o0), .o1(o1));

    // expected-result delay line.  The op is captured by R1 at the edge where it is
    // pushed (index 0); the result is registered by R6 at the edge LAT-1 later, and the
    // check at that edge runs before the shift, so it reads index LAT-2.
    reg        ev [0:LAT];
    reg [11:0] e0 [0:LAT];
    reg [11:0] e1 [0:LAT];
    integer k;
    integer errors = 0, checked = 0, sent = 0, got = 0;

    function [11:0] enc(input integer zeta, input integer inv);   // twiddle table entry
        integer t;
        begin
            t = zeta;
            if (inv) t = (t * {(Q + 1) // 2}) % Q;
            if (MONT) t = (t * 65536) % Q;
            enc = t;
        end
    endfunction

    // drive one operation: set the DUT inputs and the matching expectation
    reg        n_v;
    reg [11:0] n_e0, n_e1;
    task drive(input integer m, input integer aa, input integer bb, input integer zeta);
        integer t;
        begin
            mode <= m; a <= aa; b <= bb; z <= enc(zeta, m); v_in <= 1;
            if (m == 0) begin
                t = (bb * zeta) % Q;
                n_e0 = (aa + t) % Q;
                n_e1 = (aa + Q - t) % Q;
            end else begin
                n_e0 = ((aa + bb) * {(Q + 1) // 2}) % Q;
                n_e1 = ((((bb + Q - aa) % Q) * zeta) % Q * {(Q + 1) // 2}) % Q;
            end
            n_v = 1; sent = sent + 1;
            tick;
        end
    endtask
    task idle;
        begin v_in <= 0; n_v = 0; tick; end
    endtask

    // one clock: shift the expectation line, check the DUT output, advance
    task tick;
        begin
            @(posedge clk);
            #1;
            if (v_out !== ev[LAT-2]) begin
                errors = errors + 1;
                if (errors < 10) $display("FAIL valid mismatch t=%0t v_out=%b exp=%b", $time, v_out, ev[LAT-2]);
            end else if (ev[LAT-2]) begin
                checked = checked + 1; got = got + 1;
                if (o0 !== e0[LAT-2] || o1 !== e1[LAT-2]) begin
                    errors = errors + 1;
                    if (errors < 10) $display("FAIL result t=%0t got %0d,%0d exp %0d,%0d", $time, o0, o1, e0[LAT-2], e1[LAT-2]);
                end
            end
            for (k = LAT; k > 0; k = k - 1) begin
                ev[k] = ev[k-1]; e0[k] = e0[k-1]; e1[k] = e1[k-1];
            end
            ev[0] = n_v; e0[0] = n_e0; e1[0] = n_e1;
        end
    endtask

    integer i, j, s, seed;
    initial begin
        for (k = 0; k <= LAT; k = k + 1) begin ev[k] = 0; e0[k] = 0; e1[k] = 0; end
        n_v = 0; n_e0 = 0; n_e1 = 0;
        repeat (3) tick;
        rst <= 0;
        repeat (2) tick;

        // S1 forward: every (b, zeta); a is a mix of both
        for (i = 0; i < Q; i = i + `STRIDE)
            for (j = 0; j < Q; j = j + 1) drive(0, (j * 1237 + i * 911) % Q, j, i);
        // S2 forward: every (a, b) at several twiddles
        for (i = 0; i < Q; i = i + `STRIDE)
            for (j = 0; j < Q; j = j + 1) drive(0, i, j, (i == 0) ? 1 : (i == 1) ? Q - 1 : 1729);
        // S3 inverse: every (a, b), twiddle derived from them
        for (i = 0; i < Q; i = i + `STRIDE)
            for (j = 0; j < Q; j = j + 1) drive(1, i, j, (i + 3 * j) % Q);
        // S4 inverse: a = 0 so x = b, every (b, zeta)
        for (i = 0; i < Q; i = i + `STRIDE)
            for (j = 0; j < Q; j = j + 1) drive(1, 0, j, i);
        // S5 edge values
        for (i = 0; i < 4; i = i + 1) for (j = 0; j < 4; j = j + 1) for (s = 0; s < 2; s = s + 1) begin
            drive(s, (i < 2) ? i : Q - 4 + i, (j < 2) ? j : Q - 4 + j, (i + j) % 2 ? Q - 1 : 1);
            drive(s, (i < 2) ? i : Q - 4 + i, (j < 2) ? j : Q - 4 + j, 0);
        end
        // S6 valid bubbles: random gaps, both modes
        seed = 12345;
        for (i = 0; i < 20000; i = i + 1) begin
            seed = (seed * 1103515245 + 12345) & 32'h7fffffff;
            if (seed[17:16] == 0) idle;
            else drive(seed[20], seed[10:0] % Q, (seed >> 11) % Q, (seed >> 3) % Q);
        end
        repeat (LAT + 2) idle;
        if (got != sent) begin errors = errors + 1; $display("FAIL count sent %0d got %0d", sent, got); end

        // S7 reset flushes the valid pipe
        drive(0, 1, 2, 3); drive(0, 4, 5, 6);
        rst <= 1; v_in <= 0; n_v = 0;
        @(posedge clk); #1;
        for (k = 0; k <= LAT; k = k + 1) ev[k] = 0;
        @(posedge clk); #1;
        if (v_out !== 1'b0) begin errors = errors + 1; $display("FAIL reset did not clear valid"); end
        rst <= 0;
        repeat (LAT + 2) idle;

        if (errors == 0) $display("PASS mlkem_bfly %s: %0d results checked", "{reduction}", checked);
        else $display("FAIL mlkem_bfly {reduction}: %0d errors in %0d results", errors, checked);
        $finish;
    end
endmodule
"""
